export async function GET(request: Request) {
  try {
    const supabase = await createClient();

    const {
      data: { user },
      error: authError,
    } = await supabase.auth.getUser();

    if (authError || !user)
      return Response.json({ error: "Unauthorized" }, { status: 401 });

    const { searchParams } = new URL(request.url);

    const donorType = searchParams.get("donorType") ?? undefined;
    const fiscalYear = searchParams.get("fiscalYear") ?? undefined;
    const pipelineStage = searchParams.get("pipelineStage") ?? undefined;

    console.log(
      `[GET] Lead pipeline report filters: ${donorType}, ${fiscalYear}, ${pipelineStage}`,
    );

    const { data, error } = await supabase.rpc("lead_pipeline_report", {
      p_donor_type: donorType ?? null,
      p_fiscal_year: fiscalYear ?? null,
      p_pipeline_stage: pipelineStage ?? null,
    });

    if (error) throw error;

    const report = data as Leads.Report;

    report.fiscalYear = fiscalYear;
    report.donorType = donorType;
    report.pipelineStage = pipelineStage;

    if (report.quarterlySummary?.headers) {
      report.quarterlySummary.headers[
        report.quarterlySummary.headers.length - 1
      ] =
        report.fiscalYearOptions?.find(
          (option) => option.key === report.fiscalYear,
        )?.label ?? "All Years";
    }

    report.timestamp = new Date().toISOString();

    return Response.json(report);
  } catch (err) {
    const message = err instanceof Error ? err.message : "Unknown error";

    return Response.json({ error: message }, { status: 500 });
  }
}
